import{_ as n,o as a,c as t,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const m=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"einstieg/grundlagen/installation.md","filePath":"einstieg/grundlagen/installation.md"}'),r={name:"einstieg/grundlagen/installation.md"};function l(s,e,o,u,d,g){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Richten Sie zunächst SchILD-NRW 3 ein und stellen Sie anschließend die benötigten Reports und Zeugnisformulare bereit. Die folgenden Anleitungen führen durch die einzelnen Schritte.</p><h2 id="installation-von-schild-nrw-3" tabindex="-1">Installation von SchILD-NRW 3 <a class="header-anchor" href="#installation-von-schild-nrw-3" aria-label="Permalink to &quot;Installation von SchILD-NRW 3&quot;">​</a></h2><p>SchILD-NRW 3 benötigt den SVWS-Server. Installieren Sie deshalb zuerst den Server und anschließend das Windows-Programm. Die Anleitung beschreibt die Einrichtung am Einzelplatz oder im Netzwerk sowie die Verbindung zur Datenbank.</p><p><a href="/administration/installation/installation-svws-server-und-schild-nrw-3.html">Zur Anleitung: SVWS-Server und SchILD-NRW 3 installieren</a></p><h2 id="installation-der-basisreportsammlung" tabindex="-1">Installation der Basisreportsammlung <a class="header-anchor" href="#installation-der-basisreportsammlung" aria-label="Permalink to &quot;Installation der Basisreportsammlung&quot;">​</a></h2><p>Die Basisreportsammlung enthält Vorlagen für Listen, Bescheinigungen und weitere Ausgaben. Sie wird bei der Erstinstallation mitgeliefert und lässt sich unabhängig vom Programm aktualisieren. Die Anleitung erklärt das Herunterladen und Bereitstellen der Sammlung sowie den Schutz eigener Anpassungen.</p><p><a href="/reporting/basisreports/basisreportsammlung-herunterladen-und-aktualisieren.html">Zur Anleitung: Die Basisreportsammlung herunterladen und aktualisieren</a></p><h2 id="installation-von-zeugnisreports" tabindex="-1">Installation von Zeugnisreports <a class="header-anchor" href="#installation-von-zeugnisreports" aria-label="Permalink to &quot;Installation von Zeugnisreports&quot;">​</a></h2><p>Zeugnisreports werden als eigene Pakete für die jeweilige Schulform bereitgestellt. Laden Sie das passende Paket herunter und entpacken Sie es in die Reportstruktur. Die Anleitung zeigt, wo die Formulare abgelegt werden und wie sie in der Reportverwaltung verfügbar werden.</p><p><a href="/reporting/zeugnisformulare/zeugnisformulare-herunterladen-und-aktualisieren.html">Zur Anleitung: Zeugnisformulare herunterladen und bereitstellen</a></p>',11)])])}const p=n(r,[["render",l]]);export{m as __pageData,p as default};
